contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // run a single scenario: deposit some Ether, then try withdraw, then optionally call refund
    // params: depositAmount sent to deposit(), withdrawAmount to withdraw()
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient funds to fund deposit");

        // Make a deposit into c from this contract
        c.deposit{value: depositAmount}();

        // record balances observed before withdraw
        uint256 beforeContractBalance = address(c).balance;
        uint256 beforeThisBalance = address(this).balance;

        // attempt withdraw and capture whether it reverted
        bool withdrew;
        try c.withdraw(withdrawAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // read balances after attempt
        uint256 afterContractBalance = address(c).balance;
        uint256 afterThisBalance = address(this).balance;

        // Attempt to observe caller-specific stored balance by invoking refund on c in a try-catch
        // If refund reverts, treat as unknown; otherwise observe effect
        bool refundSucceeded;
        uint256 postRefundContractBalance;
        uint256 postRefundThisBalance;
        try c.refund() {
            refundSucceeded = true;
            postRefundContractBalance = address(c).balance;
            postRefundThisBalance = address(this).balance;
        } catch {
            refundSucceeded = false;
            postRefundContractBalance = afterContractBalance;
            postRefundThisBalance = afterThisBalance;
        }

        // General invariant to assert:
        // - If withdraw reverted, contract and this balances unchanged by that call.
        // - If withdraw succeeded, contract balance decreased by at most withdrawAmount and this balance increased by at most withdrawAmount.
        // - After any successful refund, the contract's balance does not go negative and this contract's balance increases by at most the prior contract balance.
        assert(
            (
                // withdraw reverted -> no balance change from before to after
                (!withdrew && beforeContractBalance == afterContractBalance && beforeThisBalance == afterThisBalance)
            ) || (
                // withdraw succeeded -> contract lost between 0 and withdrawAmount, this gained between 0 and withdrawAmount
                (withdrew && beforeContractBalance >= afterContractBalance && beforeContractBalance - afterContractBalance <= withdrawAmount
                    && afterThisBalance >= beforeThisBalance && afterThisBalance - beforeThisBalance <= withdrawAmount)
            )
            &&
            (
                // if refund succeeded, contract balance decreased and this increased by at most the amount refunded (i.e., not exceeding prior contract balance)
                (!refundSucceeded) || (
                    postRefundContractBalance <= afterContractBalance
                    && postRefundThisBalance >= afterThisBalance
                    && afterContractBalance - postRefundContractBalance <= afterContractBalance
                    && postRefundThisBalance - afterThisBalance <= afterContractBalance
                )
            )
        );
    }

    // receive to accept any refunds/transfers
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test the behavior of refund(): it should either transfer the caller's stored balance out (decreasing contract balance
    // by at most the prior contract balance and increasing this contract's balance by the same amount) or revert leaving balances unchanged.
    // No deposits or withdrawals are invoked here to avoid triggering other internal asserts in C.
    function run() public payable {
        // record balances before calling refund
        uint256 beforeContract = address(c).balance;
        uint256 beforeThis = address(this).balance;

        bool succeeded;
        // call refund and observe whether it reverted
        try c.refund() {
            succeeded = true;
        } catch {
            succeeded = false;
        }

        uint256 afterContract = address(c).balance;
        uint256 afterThis = address(this).balance;

        // If refund reverted, balances must be unchanged. If it succeeded, contract balance decreased by some amount d (0..beforeContract)
        // and this contract's balance increased by exactly the same amount d. Express without subtraction that can underflow in assert:
        // succeeded -> afterContract <= beforeContract && afterThis >= beforeThis && (beforeContract - afterContract) == (afterThis - beforeThis)
        // not succeeded -> afterContract == beforeContract && afterThis == beforeThis
        assert(
            (!succeeded && afterContract == beforeContract && afterThis == beforeThis)
            || (succeeded && afterContract <= beforeContract && afterThis >= beforeThis && (beforeContract - afterContract) == (afterThis - beforeThis))
        );
    }

    // receive to accept Ether transferred from C during refund
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to withdraw and assert the invariant
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient test balance for deposit");
        // 1) deposit depositAmount into c from this contract
        c.deposit{value: depositAmount}();

        // record balances visible from public surface
        uint256 beforeContractBalance = address(c).balance;
        // c has no public getter for balances (it's private), but there is no getter — however the test can rely
        // on observable effects: after withdraw, address(c).balance should decrease and this contract's balance increase.

        // 2) attempt withdraw(withdrawAmount) and catch revert status
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBalance = address(c).balance;
        // Now assert the general rule:
        // If withdraw did not revert, then the contract's stored balance for this caller decreased by exactly withdrawAmount
        // and address(c).balance decreased by at least withdrawAmount. We cannot read internal balances mapping, so
        // we express the rule in terms of observable contract balance change and that withdraw succeeds only when
        // amount was <= caller's stored balance. The best observable guarantee: if withdraw succeeded then
        // afterContractBalance + withdrawAmount <= beforeContractBalance (contract lost at least withdrawAmount).
        // Also, if withdraw succeeded then withdrawAmount <= beforeContractBalance (since contract must have had funds to pay).

        assert(reverted || (afterContractBalance + withdrawAmount <= beforeContractBalance && withdrawAmount <= beforeContractBalance));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address creator;
    constructor(C _c) { c = _c; creator = address(this); }

    // Try to invoke migrateTo as creator and assert that on success the contract's balance becomes zero
    // Parameters: target address to migrate to, and an amount to pre-fund c so migrate has something to send.
    function run(address to, uint256 fundAmount) public payable {
        // ensure this test contract has enough Ether to fund c if requested
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Fund c by depositing fundAmount (this will call C.deposit which may revert if overflow in balances mapping occurs)
        // To avoid hitting deposit's internal assert accidentally when fundAmount is zero, allow zero too.
        if (fundAmount > 0) {
            c.deposit{value: fundAmount}();
        }

        // Record contract balance before migrate
        uint256 before = address(c).balance;

        // Attempt migrateTo and capture whether it reverted
        bool reverted;
        try c.migrateTo(to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: If migrateTo did not revert (i.e., was called by the creator successfully), then all Ether held by c was sent out and its balance is zero afterwards.
        // We express this as: either the call reverted, or after == 0 and before >= after (i.e., funds drained).
        // Require that when not reverted, after == 0 and before >= 0 trivially holds.
        assert(reverted || after == 0);
    }

    // Allow this contract to receive refunded Ether from c
    receive() external payable {}
}

