contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs: depositAmount to deposit into c and withdrawAmount to attempt withdraw
    function run(uint256 depositAmount, uint256 withdrawAmount) public payable {
        // ensure this contract can send depositAmount if nonzero
        if (depositAmount > 0) {
            require(address(this).balance >= depositAmount, "insufficient funds to deposit");
        }

        // record balances before any interaction
        uint256 contractBalanceBefore = address(c).balance;
        // there's no public getter for balances mapping, so we observe effects via contract balance and revert behavior

        // perform a deposit into c from this contract (msg.sender for c will be this contract)
        if (depositAmount > 0) {
            c.deposit{value: depositAmount}();
        }

        // record state after deposit
        uint256 contractBalanceAfterDeposit = address(c).balance;

        // Now attempt withdraw; capture whether it reverts
        bool withdrew;
        uint256 contractBalanceAfterWithdraw;
        // Try-catch to detect revert
        try c.withdraw(withdrawAmount) {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        contractBalanceAfterWithdraw = address(c).balance;

        // General rule (single assert):
        // If withdraw succeeded then contract balance decreased by exactly withdrawAmount (i.e., funds left c)
        // and that withdrawAmount could not exceed the depositor's balance as implied by contract behavior: if withdraw succeeded then withdrawAmount <= contractBalanceAfterDeposit (conservative observable)
        // If withdraw reverted then withdrawAmount was greater than the caller's recorded balance before withdraw; we express this by stating that if it reverted then withdrawAmount > 0 implies contract balance did not change.
        // Combine into one assertion relating observed balances and withdraw outcome.
        assert(
            // Case: withdraw succeeded -> contract balance decreased exactly by withdrawAmount
            (withdrew && contractBalanceAfterDeposit == contractBalanceAfterWithdraw + withdrawAmount)
            // Case: withdraw reverted -> contract balance unchanged
            || (!withdrew && contractBalanceAfterDeposit == contractBalanceAfterWithdraw)
        );
    }

    // receive to accept Ether when c.transfer sends Ether to this contract during tests (not expected here but safe)
    receive() external payable {}
}

