contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // test parameter: deposit amount
    function run(uint256 amount) public payable {
        // ensure this test contract has enough ETH to send
        require(address(this).balance >= amount);

        // read before-values via public observable surface
        // note: balances is not public in C, so use behavior through withdraw/refund? Actually balances isn't public — but we can observe effects via contract balance and attempt to withdraw.
        // To observe the recorded balance for this contract we will: deposit, then attempt to withdraw the same amount and observe success. However the specification asks to test deposit directly and observe state; to stay within allowed public surface we only rely on address(c).balance and the success of deposit (revert flag).

        uint256 beforeContractBal = address(c).balance;

        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterContractBal = address(c).balance;

        // If deposit did not revert, contract balance must increase by exactly amount.
        // Also, if deposit succeeded, recorded balance for this caller must have increased by exactly amount — we check this by attempting to withdraw `amount` (which will succeed only if recorded balance >= amount).
        bool withdrawReverted;
        if (!reverted) {
            // try to withdraw amount; this will revert if recorded balance < amount
            try c.withdraw(amount) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            withdrawReverted = true; // irrelevant when deposit reverted
        }

        // After withdraw attempt, contract balance decreased by at least amount if withdraw succeeded
        uint256 finalContractBal = address(c).balance;

        // General rule: either deposit reverted, or (contract balance increased by amount AND withdraw of that amount succeeds and decreases contract balance by at least amount)
        assert(reverted || (afterContractBal == beforeContractBal + amount && withdrawReverted == false && finalContractBal <= afterContractBal - amount));
    }

    // allow receiving ETH when withdraw/refund sends funds
    receive() external payable {}
}

