contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt a deposit of `amount` and check balances
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);

        // observe contract and recorded balance before
        uint256 beforeContractBal = address(c).balance;
        // call deposit (may revert)
        bool depositReverted;
        try c.deposit{value: amount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }
        // read observable values after
        uint256 afterContractBal = address(c).balance;
        // The mapping balances is not public in C, so we cannot read it directly. However, when deposit succeeds
        // it must have increased the caller's recorded balance by exactly amount. We can test this by attempting
        // to withdraw that amount: if deposit succeeded then withdraw(amount) should not revert (because require)
        // and after withdraw the contract balance should decrease by at least amount. We perform that withdraw only
        // when deposit did not revert and capture whether it reverts.
        bool withdrawReverted;
        if (!depositReverted) {
            try c.withdraw(amount) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            withdrawReverted = true;
        }
        uint256 finalContractBal = address(c).balance;

        // General rule: either deposit reverted, or deposit increased both the recorded caller balance by exactly
        // `amount` and the contract's Ether balance by exactly `amount`. We observe the recorded-balance effect
        // by successful withdraw: if deposit succeeded then withdraw(amount) must succeed (require(amount <= balances[msg.sender]))
        // and reduce the contract's balance by at least amount; combining a non-reverting deposit with a successful
        // withdraw of the same amount implies the intermediate increase was exactly amount and the contract balance
