    constructor(C _c) {
        c = _c;
        // record the deploying address of C as creator (constructor of C set creator = msg.sender)
        // The checker deploys a fresh C with msg.sender == this contract, so this contract is the creator.
        creatorAddr = payable(address(this));
    }

    // Input: a destination address to migrate funds to.
    // We will only call migrateTo as the creator (this contract), which should be allowed.
    function run(address payable to) public payable {
        // no precondition on `to` (can be zero address or any); simply call migrateTo as creator

        // Observe recorded balance for this contract before migrateTo
        // balances mapping has no public getter, so we cannot read it directly. However, the contract exposes
        // no getter for balances, so we cannot observe per-address recorded balances. Instead, we must rely
        // on observable effects: address(c).balance and that migrateTo only allowed for creator.
        // To craft a useful general rule different from prior ones, we assert that if migrateTo succeeds when
        // called by the creator, then address(c).balance becomes zero afterwards (all Ether moved out).

        // Ensure there's some Ether in c to make the property meaningful: deposit some Ether into c first.
        uint256 depositAmount = msg.value;
        if (depositAmount > 0) {
            // send Ether to c via deposit; require this contract has the funds (msg.value provided to run)
            // perform deposit; if deposit reverts, we still can attempt migrateTo — but then contract balance may be zero
            // so the general invariant must hold regardless.
            try c.deposit{value: depositAmount}() {
                // deposit succeeded
            } catch {
                // deposit reverted; continue
            }
        }

        // Capture contract balance before migrate
        uint256 before = address(c).balance;

        bool reverted;
        try c.migrateTo(to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 after = address(c).balance;

        // General rule: If migrateTo was called by the creator (this contract) and it succeeded (did not revert),
        // then the contract's balance becomes zero afterwards. If it reverted, the balance may be unchanged.
        assert((reverted && after <= before) || (!reverted && after == 0));
    }

    // allow this test contract to receive Ether
    receive() external payable {}
}

