contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry point: no ether sent to this call; we will first deposit some ether into c
    function run(uint256 depositAmount) public payable {
        // require this test contract can fund the initial deposit
        require(address(this).balance >= depositAmount);

        // record balances before any operations
        uint256 contractBalBefore = address(c).balance;
        uint256 recordedBefore = c.balances(address(this));

        // try to deposit depositAmount into c on behalf of this contract
        bool depReverted;
        try c.deposit{value: depositAmount}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        // read recorded balance after deposit attempt
        uint256 recordedAfterDeposit = c.balances(address(this));
        uint256 contractBalAfterDeposit = address(c).balance;

        // Now attempt refund()
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        // read recorded balance and contract balance after refund attempt
        uint256 recordedFinal = c.balances(address(this));
        uint256 contractBalFinal = address(c).balance;

        // General rule asserted:
        // Either refund reverted and recorded balance unchanged, or refund succeeded and recorded balance is zero.
        // Additionally, the contract's Ether balance must decrease by at least the decrease in the recorded balance
        // (i.e., contract lost >= (recordedAfterDeposit - recordedFinal)).
        assert(
            (
                refundReverted && recordedFinal == recordedAfterDeposit
            ) || (
                !refundReverted && recordedFinal == 0
            )
        );

        // Additional invariant linking Ether movement to recorded balance decrease
        // (use a second assert by combining into the single final assert requirement: we combine both conditions)
        assert(
            (
                refundReverted && recordedFinal == recordedAfterDeposit && contractBalFinal + 0 <= contractBalAfterDeposit
            ) || (
                !refundReverted && recordedFinal == 0 && contractBalAfterDeposit >= contractBalFinal && (contractBalAfterDeposit - contractBalFinal) >= (recordedAfterDeposit - recordedFinal)
            )
        );
    }

    // receive to accept Ether refunds
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We cannot access c.balances (it's not public), so we observe only address(c).balance changes.
    // The test: send some Ether via deposit (may revert) and then call refund(); ensure either refund reverted and contract balance unchanged
    // or refund succeeded and the contract's Ether balance decreased by at least the amount that the contract's balance increased due to the deposit attempt.
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        uint256 contractBalBefore = address(c).balance;

        // attempt deposit; record whether it reverted
        bool depositReverted;
        try c.deposit{value: depositAmount}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 contractBalAfterDeposit = address(c).balance;

        // attempt refund; record whether it reverted
        bool refundReverted;
        try c.refund() {
            refundReverted = false;
        } catch {
            refundReverted = true;
        }

        uint256 contractBalFinal = address(c).balance;

        // General rule (single assert):
        // If refund reverted then contract balance must equal balance after deposit attempt (no change by refund).
        // Otherwise refund succeeded and the contract's balance decrease from after-deposit to final is at least the increase caused by the deposit attempt
        // (i.e., contractBalAfterDeposit - contractBalBefore <= contractBalAfterDeposit - contractBalFinal).
        // Rearranged: if refund succeeded then contractBalFinal <= contractBalBefore.
        assert(
            (refundReverted && contractBalFinal == contractBalAfterDeposit)
            || (!refundReverted && contractBalFinal <= contractBalBefore)
        );
    }

    // allow receiving Ether from c.refund()
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address public deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We test two properties depending on who calls migrateTo.
    // Parameters:
    // - to: destination address for migrateTo call.
    // - sendDeposit: amount this test will try to deposit before migrate (to create some balance observable via address(c).balance).
    // The function is payable so the test can send Ether for deposit; require ensures tester has funds.
    function run(address to, uint256 sendDeposit) public payable {
        require(address(this).balance >= sendDeposit);

        // Record contract balance before any actions
        uint256 balBefore = address(c).balance;

        // Try deposit from this test contract to increase contract balance (may revert inside C.deposit)
        bool depositReverted;
        try c.deposit{value: sendDeposit}() {
            depositReverted = false;
        } catch {
            depositReverted = true;
        }

        uint256 balAfterDeposit = address(c).balance;

        // Attempt migrateTo and record whether it reverted
        bool migrateReverted;
        try c.migrateTo(to) {
            migrateReverted = false;
        } catch {
            migrateReverted = true;
        }

        uint256 balAfterMigrate = address(c).balance;

        // General rule (single assert):
        // If migrateTo reverted, then contract balance unchanged by migrateTo (i.e., balAfterMigrate == balAfterDeposit).
        // If migrateTo succeeded, then contract balance is zero (contract drained to `to`) and the balance never increased due to migrateTo
        // (i.e., balAfterMigrate == 0 and balAfterMigrate <= balAfterDeposit).
        // Additionally, only the creator can make migrateTo succeed: if migrate succeeded and caller (this contract) is not the creator, that's a violation
        // but we cannot read creator directly; however the intended contract requires creator==msg.sender, so from the fresh deployer semantics
        // the test contract is not the original external creator — but to keep the assert purely over observables, we assert the two cases about balances and revert flag.
        assert(
            (migrateReverted && balAfterMigrate == balAfterDeposit)
            || (!migrateReverted && balAfterMigrate == 0)
        );
    }

    // allow receiving Ether if migrateTo or refund/withdraw transfer to this contract
    receive() external payable {}
}

